using System;using System.IO;using System.Globalization;using System.Collections.Generic;using NeonSyndicate;using UnityEngine;
class Export {
static void Write(string root,string name,Dictionary<string,MeshBuilder> groups){using(StreamWriter f=new StreamWriter(Path.Combine(root,name+".obj"))){int offset=1;foreach(KeyValuePair<string,MeshBuilder> part in groups){f.WriteLine("g "+part.Key);foreach(Vector3 p in part.Value.Vertices)f.WriteLine(string.Format(CultureInfo.InvariantCulture,"v {0:R} {1:R} {2:R}",p.x,p.y,p.z));IReadOnlyList<int> t=part.Value.Triangles(0);for(int i=0;i<t.Count;i+=3)f.WriteLine("f "+(t[i]+offset)+" "+(t[i+1]+offset)+" "+(t[i+2]+offset));offset+=part.Value.VertexCount;Console.WriteLine(name+" / "+part.Key+" : "+t.Count/3+" triangles");}}}
static int Main(string[] args){Directory.CreateDirectory(args[0]);foreach(string id in new[]{"lofts","forge"}){VenueBinding04C b=new VenueBinding04C{Definition=new VenueDefinition04C{Id=id},Building=new Building{Height=id=="lofts"?13.5f:16},Width=30,Depth=30};MeshBuilder structure=new MeshBuilder(1),porch=new MeshBuilder(1);GothicHeartH3.Structure(structure,b);Dictionary<string,MeshBuilder> old=new Dictionary<string,MeshBuilder>();old.Add("masonry",structure);foreach(ArtPlacementH2 p in GothicHeartH3.ServicePlan(b)){string role=AscensionArtH2.Role(p.Model);if(!old.ContainsKey(role))old.Add(role,new MeshBuilder(1));MeshBuilder m=AscensionArtH2.Decode(File.ReadAllBytes("Assets/NeonSyndicate/Resources/AscensionH2/Meshes/"+p.Model+"_low.bytes"));AscensionArtH2.Append(old[role],m,p.Position,p.Yaw,p.Scale);if(p.Model=="processional_stair" || p.Model=="gallery_rail")AscensionArtH2.Append(porch,m,p.Position,p.Yaw,p.Scale);}Write(args[0],id+"_before",old);structure=new MeshBuilder(1);GothicHeartH3.Structure(structure,b);Write(args[0],id+"_after",HeartPlanFR01.ScienceService(id,structure,porch).Surfaces);}Write(args[0],"court_after",HeartPlanFR01.ScienceCourt().Surfaces);return 0;}}
